INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(114299, 'ruRU', '', 'Ты сможешь зацепиться за ту точку наверху стены. Следуй за мной!', 24330),
(114304, 'ruRU', '', 'Мамочка!', 24330),
(114305, 'ruRU', '', 'Спасибо -тебе-. Я даже не могу выразить свою благодарность.', 24330),
(114315, 'ruRU', '', 'Мы не пойдём туда без лишней пары рук, и это окончательно!', 24330),
(114321, 'ruRU', '', 'Может, ты сможешь нам помочь. Старая мастерица магии бродит призраком в этих руинах. Её нужно упокоить.', 24330),
(114325, 'ruRU', '', 'Держись рядом, эти призраки в последнее время взбудоражены из-за всей той суеты в Азсуне.', 24330),
(114326, 'ruRU', '', 'Мы приближаемся. Держи других духов на расстоянии. Мастера остаются сильны даже в смерти.', 24330),
(114333, 'ruRU', '', 'Встретимся дальше на мосту. Но сперва мне нужно найти своё оружие.', 24330),
(114334, 'ruRU', '', 'Мы должны пробудить благородные сердца моего народа.', 24330),
(114335, 'ruRU', '', 'ТЫ... должен показать им, что Азерот не забыл о них.', 24330),
(114336, 'ruRU', '', 'Обрети покой, дух!', 24330),
(114337, 'ruRU', '', 'Демонический лорд Лохабер скрывается где-то в этом бардаке наверху. У меня нет желания подходить к воротам только для того, чтобы убить одного демона. В итоге нам пришлось бы прорубаться через сотни.\n\nОдно, что я усвоила, пока он был у нас в плену — у него немалое самолюбие. Так что я вызову его на бой перед лицом всех остальных.\n\n<Малис сдерживает смешок, совершенно не подобающий Стражу.>\n\nДай мне знать, когда будешь готов, охотник на демонов.', 24330),
(114354, 'ruRU', '', 'Руолин, это было прекрасно!', 24330),
(114356, 'ruRU', '', 'Лохабер! Выходи, демон, встреться с нами лицом к лицу. Если, конечно, тебе не страшно.', 24330),
(114393, 'ruRU', '', 'Покойся теперь, сестра. Твои мучения окончены.', 24330),
(114394, 'ruRU', '', 'Мы в долгу перед тобой. Я передам весть о твоих деяниях здесь принцу Фарондису.', 24330),
(114408, 'ruRU', '', 'Лучники, выбирайте цели!', 24330),
(114420, 'ruRU', '', 'Йаррр! Это ж старина Ушастый, ужас открытых морей! Вот наш шанс, парни, хватай их!', 24330),
(114432, 'ruRU', '', 'Как же это предсказуемо! Я знала, что ты придёшь.', 24330),
(114438, 'ruRU', '', 'У меня есть то, за чем я пришла. Но я осталась лишь для того, чтобы покончить с тобой... раз и навсегда!', 24330),
(114440, 'ruRU', '', 'У меня уже есть Саргеритовый Краеугольный Камень. Но я осталась лишь для того, чтобы покончить с тобой... раз и навсегда.', 24330),
(114442, 'ruRU', '', 'И теперь вы, глупцы, попали в мою ловушку. Посмотрим, как вы справитесь во тьме.', 24330),
(114465, 'ruRU', '', 'Я разведаю путь вперёд в поисках удобной точки обзора. Встретимся у городской стены, когда у тебя будет крюк.', 24330),
(114478, 'ruRU', '', 'Нежить, мразь! Само твоё существование — оскорбление для всех, кто потерял семьи из-за Плети. Сними эту накидку и ползи обратно в свою могилу, пока я не отправила тебя туда сам!', 24330),
(114479, 'ruRU', '', 'Полагаю, тебе просто придётся довериться мне, не так ли?', 24330),
(114480, 'ruRU', '', 'Такие пришлые, как ты, виновны в том, что подорвали силы Алого Крестового похода! Мы бы искоренили нежить из этого мира, и Пылающий Легион никогда не зашёл бы так далеко! Прочь!', 24330),
(114483, 'ruRU', '', 'Вижу, ты друг Крестового похода. Мне удалось вывезти кое-какое снаряжение из Монастыря в попытке собрать средства для нашего ордена. Мы не успокоимся, пока нежить не будет изгнана из Азерота!\n\nИмей в виду, что ты и тебе подобные довели нас до грани разорения, так что продаю я не дёшево.', 24330),
(114486, 'ruRU', '', 'Ах, прославленная Сумеречная Стража. Если бы ты смог освободить часть их припасов, это сильно помогло бы нашему делу.', 24330),
(114487, 'ruRU', '', 'Хорошая работа. Это должно их притормозить.', 24330),
(114494, 'ruRU', '', 'Свет Элуны больше не освещает диких зверей этого грота. Они стали грозными совозверями и опасны для всех.', 24330),
(114506, 'ruRU', '', 'Моя давняя ученица всё ещё живёт в городе. Было время, когда я думал, что могу ей доверять. Проследи, чтобы она поняла, что происходит с предателями.', 24330),
(114507, 'ruRU', '', 'Прекрасно сделано. Жаль, что я не мог оказаться там сам.', 24330),
(114508, 'ruRU', '', 'Шар''тос вернулся в своё гнездовье. Прекрати его мучения, прежде чем он распространит порчу, которой поддался.', 24330),
(114509, 'ruRU', '', 'Отлично сделано! Будем надеяться, что эта глава в жизни Шар''тоса будет забыта.', 24330),
(114510, 'ruRU', '', 'Волки в окрестностях стали слишком дерзкими. Время сократить стаю.', 24330),
(114511, 'ruRU', '', 'День выиграли! Отлично сражался, защитник.', 24330),
(114520, 'ruRU', '', 'Я отправлюсь к Трещине Ужаса, как только донесу это признание до нужных людей.', 24330),
(114521, 'ruRU', '', 'Можешь считать меня одним из тех, кто готов сражаться с Пылающим Легионом рядом с тобой.', 24330),
(114536, 'ruRU', '', 'Осторожно!', 24330),
(114537, 'ruRU', '', 'Осторожно, он кусается.', 24330);
